      '有人說：「吳國已經立國將近一百年，不可能一下子全打下來。現在快到夏天，大水就要來了，疾病也會流行，應該等到冬天再大舉進攻。」',
      '杜預說：「從前樂毅靠濟西一場仗，就打敗了強大的齊國。現在我軍的聲威已經振作起來，就像劈竹子，劈開幾節以後，下面的都會順著刀口裂開，不必再費力了。」',
