    example: '這支球隊從預賽一路勢如破竹，連勝八場打進決賽。',
    situation: '小琳把數學講義從簡單的題目開始做，越做越有信心，後面的題目勢如破竹，一個晚上就寫完了。',
    note: '「眾軍會議」是各路軍隊的將領聚在一起商量，「百年之寇」是立國將近百年的敵人，指吳國，「克」是打下來，「向暑」是快到夏天，「水潦」是大水(「潦」念ㄌㄠˋ)，「疾疫」是傳染病，「俟」是等待(念ㄙˋ)，「大舉」是大規模進攻，「預」是杜預，西晉的大將，「樂毅」是戰國時燕國的名將，「濟西」是濟水西邊，「並」是吞併，「振」是振作，「數節之後」是劈開幾節以後，「迎刃而解」是順著刀口裂開，「無復著手處」是不用再費力，「指授」是指揮，「徑造」是直接到達，「秣陵」約在今南京附近，三國吳改名建業，是吳國的都城(《成語典》)，「束手」是投降，「謝」是道歉。',
