      '這時公孫述派大將李育帶兵來救隗囂，守住上邽。光武帝留下蓋延、耿弇包圍上邽，自己回東邊去了。',
      '光武帝寫信給岑彭：「這兩座城如果攻下來，就可以帶兵往南攻打蜀地的敵人。」',
