    original: '王魯爲當塗宰，頗以資產爲務。會部民連狀訴主簿貪賄於縣尹，魯乃判曰：『汝雖打草，吾已蛇驚。』爲好事者口實焉。',
    source: '鄭文寶《南唐近事》卷二(〈南唐近事〉revid 1503836)',
    meaning: '打草叢把草裡的蛇嚇著了；原本比喻懲罰了甲，乙也跟著警惕；後來多比喻做事不小心，讓對方發覺而先有防備。',
    example: '警察還沒查清楚之前不公開消息，免得打草驚蛇，讓嫌犯跑了。',
    situation: '哥哥想替媽媽準備生日驚喜，提醒全家先別問媽媽想要什麼，免得打草驚蛇。',
    note: '「王魯」是南唐的官員，「當塗」是縣名，《成語典》說或許是今安徽當塗，「宰」是縣令，「頗以資產爲務」是很注重累積自己的財產(「爲」同「為」)，「部民」是他管轄的百姓，「連狀」是聯名寫狀子，「訴」是控告，「主簿」是管文書的官員，「貪賄」是收賄賂，「縣尹」是縣的長官，指王魯，「判」是在狀子上批字，「汝」是你們，「吾已蛇驚」是我這條蛇已經被嚇到了，意思是告的雖然是主簿，王魯自己也心虛害怕，「好事者」是喜歡談論的人，「口實」是說話的話題。',
