    panels: [
      '韓熙載是北海武將家的子弟，起初和李穀是好朋友。後唐明宗時，韓熙載要往南投奔吳國，李穀送他到正陽。',
      '喝酒喝到盡興、要分別的時候，韓熙載對李穀說：「江南如果用我當宰相，我一定率兵長驅直入，平定中原。」',
      '李穀說：「中原如果用我當宰相，拿下江南就像伸手到袋子裡拿東西一樣容易。」',
      '後來後周的軍隊出兵淮河一帶，派李穀當將領去攻取淮南，韓熙載卻沒能有什麼作為。',
    ],
    original: '熙載，北海將家子也，初與李穀相善。明宗時，熙載南奔吳，穀送至正陽，酒酣臨訣，熙載謂穀曰：「江左用吾為相，當長驅以定中原。」穀曰：「中國用吾為相，取江南如探囊中物爾。」及周師之征淮也，命穀為將，以取淮南，而熙載不能有所為也。',
    source: '歐陽脩《新五代史‧南唐世家》(〈新五代史/卷62〉revid 1674689);原文作「探囊中物」,《成語典》說「探囊取物」語本此文',
    meaning: '伸手到袋子裡拿東西；比喻事情非常容易辦到。',
    example: '對他來說，修好這台腳踏車就像探囊取物一樣簡單。',
    situation: '哥哥練了一整個暑假的投籃，校內比賽罰球得分對他來說如同探囊取物。',
    note: '「熙載」是韓熙載，「北海」是地名，「將家子」是武將家的子弟，「相善」是很要好，「明宗」是五代後唐的明宗皇帝，「南奔吳」是往南投奔吳國，「穀」是李穀，「正陽」是地名，「酒酣」是喝酒喝到盡興(「酣」念ㄏㄢ)，「臨訣」是將要分別，「江左」是江南，「長驅」是率兵一路前進，「中原」和「中國」都指北方中原地區，「探囊中物」是伸手拿袋子裡的東西，「周師」是後周的軍隊，「征淮」是出兵淮河一帶，「淮南」是淮河以南。',
