    original: '蕭丞相營作未央宮，立東闕、北闕、前殿、武庫、太倉。高祖還，見宮闕壯甚，怒，謂蕭何曰：「天下匈匈苦戰數歲，成敗未可知，是何治宮室過度也？」蕭何曰：「天下方未定，故可因遂就宮室。且夫天子四海為家，非壯麗無以重威，且無令後世有以加也。」高祖乃說。',
