    original: '先是，紹興五年，飛遣梁興等布德意，招結兩河豪傑，……其所揭旗以「岳」為號，父老百姓爭挽車牽牛，載糗糧以餽義軍，頂盆焚香迎候者，充滿道路。……金將軍韓常欲以五萬眾內附。飛大喜，語其下曰：「直抵黃龍府，與諸君痛飲爾！」',
